class Solution {
    public void setZeroes(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        boolean[] rowZero = new boolean[m];
        boolean[] colZero = new boolean[n];

        // 第一阶段：只记录，绝不修改矩阵，否则会污染后续判断
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == 0) {
                    rowZero[i] = true;
                    colZero[j] = true;
                }
            }
        }

        // 第二阶段：按记录清零
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (rowZero[i] || colZero[j]) {
                    matrix[i][j] = 0;
                }
            }
        }
    }
}

class Solution {
    public void setZeroes(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;

        // 先记住第一行、第一列原本有没有 0（它们自己也要被清零，但会被标记覆盖）
        boolean row0HasZero = false;
        boolean col0HasZero = false;
        for (int j = 0; j < n; j++) if (matrix[0][j] == 0) row0HasZero = true;
        for (int i = 0; i < m; i++) if (matrix[i][0] == 0) col0HasZero = true;

        // 用第一行第一列当标记区，注意从 1 开始
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                if (matrix[i][j] == 0) {
                    matrix[i][0] = 0;
                    matrix[0][j] = 0;
                }
            }
        }

        // 按标记清零，跳过第一行第一列（那是标记区，不能提前抹掉）
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                if (matrix[i][0] == 0 || matrix[0][j] == 0) {
                    matrix[i][j] = 0;
                }
            }
        }

        // 最后才处理第一行、第一列
        if (row0HasZero) {
            for (int j = 0; j < n; j++) matrix[0][j] = 0;
        }
        if (col0HasZero) {
            for (int i = 0; i < m; i++) matrix[i][0] = 0;
        }
    }
}

class Solution {
    public void setZeroes(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        boolean col0HasZero = false;

        // 打标记：matrix[0][0] 兼职表示第 0 行，col0HasZero 表示第 0 列
        for (int i = 0; i < m; i++) {
            if (matrix[i][0] == 0) col0HasZero = true;
            for (int j = 1; j < n; j++) {
                if (matrix[i][j] == 0) {
                    matrix[i][0] = 0;
                    matrix[0][j] = 0;
                }
            }
        }

        // 倒序清零：保证读到 matrix[0][j] 标记时它还没被清掉
        for (int i = m - 1; i >= 1; i--) {
            for (int j = n - 1; j >= 1; j--) {
                if (matrix[i][0] == 0 || matrix[0][j] == 0) {
                    matrix[i][j] = 0;
                }
            }
        }

        // 最后用 matrix[0][0] 决定第一行；用 col0HasZero 决定第一列
        if (matrix[0][0] == 0) {
            for (int j = 0; j < n; j++) matrix[0][j] = 0;
        }
        if (col0HasZero) {
            for (int i = 0; i < m; i++) matrix[i][0] = 0;
        }
    }
}
